// Called by the engine when a Fighting Spirit is summoned
CallMatchAvatar <- function ()
{
	if (eventCounter == 4)
	{
		eventCounter++;
		// One-shot request for the Fighting Spirit clash menu
		CMND_BTL_DISABLE_RETURN_MENU("KsnBtlMenu");
		CMND_BTL_SET_EVPARAM(44010110);
		suspend();
		CMND_BTL_SET_KESHIN_INVINCIBLE(true, "para_cp0009");
	}
};
